import 'package:flutter/material.dart';
import '../../services/api_service.dart';

class PaymentsScreen extends StatefulWidget{const PaymentsScreen({super.key});@override State<PaymentsScreen> createState()=>_PaymentsScreenState();}
class _PaymentsScreenState extends State<PaymentsScreen>{List items=[],students=[],subscriptions=[];bool loading=true;List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):(x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[]);int id(dynamic x)=>int.tryParse('${x['id']}')??0;void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final r=await Future.wait([ApiService.get('payments'),ApiService.get('students'),ApiService.get('subscriptions')]);if(mounted)setState((){items=list(r[0]);students=list(r[1]);subscriptions=list(r[2]);loading=false;});}catch(e){if(mounted){setState(()=>loading=false);msg(e);}}}
 Future<void> form({dynamic item})async{if(students.isEmpty){msg(Exception('أضف طالبًا أولًا.'));return;}int studentId=id(item?['student']??{'id':item?['student_id']});int? subscriptionId=id(item?['subscription']??{})==0?int.tryParse('${item?['subscription_id']??''}'):id(item?['subscription']);final amount=TextEditingController(text:'${item?['amount']??''}'),date=TextEditingController(text:'${item?['paid_on']??DateTime.now().toIso8601String().substring(0,10)}'),method=TextEditingController(text:'${item?['method']??'نقدي'}');final key=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(dc)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:Text(item==null?'إضافة دفعة':'تعديل الدفعة'),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:studentId,decoration:const InputDecoration(labelText:'الطالب *'),items:students.map((s)=>DropdownMenuItem<int>(value:id(s),child:Text('${s['name']}'))).toList(),onChanged:(v){if(v!=null)set(()=>studentId=v);}),Builder(builder:(_){final av=subscriptions.where((s){final sid=id(s['student']??{});return sid==studentId||'${s['student_id']??''}'=='$studentId';}).toList();if(subscriptionId!=null&&!av.any((s)=>id(s)==subscriptionId))subscriptionId=null;return DropdownButtonFormField<int?>(value:subscriptionId,decoration:const InputDecoration(labelText:'الاشتراك (اختياري)'),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون اشتراك')),...av.map((s)=>DropdownMenuItem<int?>(value:id(s),child:Text('${s['subject']??''} • ${s['amount']??0}')))],onChanged:(v)=>set(()=>subscriptionId=v));}),TextFormField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'المبلغ *'),validator:(v)=>double.tryParse(v??'')==null?'مبلغ غير صحيح':null),TextFormField(controller:date,decoration:const InputDecoration(labelText:'التاريخ YYYY-MM-DD')),TextFormField(controller:method,decoration:const InputDecoration(labelText:'طريقة الدفع'))])),actions:[TextButton(onPressed:()=>Navigator.pop(dc,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(key.currentState!.validate())Navigator.pop(dc,true);},child:const Text('حفظ'))])));if(ok==true){try{final body={'student_id':studentId,'subscription_id':subscriptionId,'amount':double.parse(amount.text),'paid_on':date.text.trim(),'method':method.text.trim()};if(item==null)await ApiService.post('payments',body);else await ApiService.put('payments/${id(item)}',body);await load();}catch(e){msg(e);}}for(final c in[amount,date,method])c.dispose();}
 Future<void> remove(dynamic p)async{final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:const Text('حذف الدفعة'),content:const Text('هل تريد حذف هذه الدفعة؟'),actions:[TextButton(onPressed:()=>Navigator.pop(dc,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(dc,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('payments/${id(p)}');await load();}catch(e){msg(e);}}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المدفوعات'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>form(),icon:const Icon(Icons.add),label:const Text('إضافة دفعة')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,12,16,90),itemCount:items.length,itemBuilder:(_,i){final p=items[i],student=p['student'],subscription=p['subscription'];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.payments)),title:Text('${student?['name']??'طالب'}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('الاشتراك: ${subscription?['subject']??'غير مرتبط'}\n${p['paid_on']??''} • ${p['method']??''}'),isThreeLine:true,trailing:Wrap(mainAxisSize:MainAxisSize.min,children:[Text('${p['amount']??0}'),IconButton(onPressed:()=>form(item:p),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(p),icon:const Icon(Icons.delete))])));}));
}
